  return changes;
}

// Better LCS implementation that tracks position in both sequences
function getLCSIndices(base, side) {
  const n = base.length;
  const m = side.length;

  // Greedy LCS: walk from start, match when equal
  const baseIndices = [];
  const sideIndices = [];
  let i = 0;
  let j = 0;

  while (i < n && j < m) {
    if (base[i] === side[j]) {
      baseIndices.push(i);
      sideIndices.push(j);
      i++;
      j++;
    } else {
      const remainingBase = n - i;
      const remainingSide = m - j;
      if (remainingBase > remainingSide) {
        i++;
      } else if (remainingSide > remainingBase) {
        j++;
      } else {
        i++;
      }
    }
  }

  return { baseIndices, sideIndices };
}

// Get changes (hunks) from comparing side against base
function getChanges(side, base) {
  const { baseIndices, sideIndices } = getLCSIndices(base, side);
  const changes = [];

  let lastBaseIdx = 0;
  let lastSideIdx = 0;

  for (let i = 0; i < baseIndices.length; i++) {
    const currBaseIdx = baseIndices[i];
    const currSideIdx = sideIndices[i];

    // Lines between lastBaseIdx and currBaseIdx in base map to lines between lastSideIdx and currSideIdx in side
    if (lastBaseIdx !== currBaseIdx || lastSideIdx !== currSideIdx) {
      changes.push({
        baseStart: lastBaseIdx,
        baseEnd: currBaseIdx,
        sideStart: lastSideIdx,
        sideEnd: currSideIdx,
      });
    }

    lastBaseIdx = currBaseIdx + 1;
    lastSideIdx = currSideIdx + 1;
  }

  // Handle remaining lines
  if (lastBaseIdx !== base.length || lastSideIdx !== side.length) {
    changes.push({
      baseStart: lastBaseIdx,
      baseEnd: base.length,
      sideStart: lastSideIdx,
      sideEnd: side.length,
    });
  }

  // Filter out empty changes
  return changes.filter(
    (c) => c.baseStart !== c.baseEnd || c.sideStart !== c.sideEnd
  );
}

// Group overlapping changes into regions
function getRegions(mineChanges, theirsChanges, base) {
  // Merge and sort changes
  const allChanges = [
    ...mineChanges.map((c) => ({ ...c, side: 'mine' })),
    ...theirsChanges.map((c) => ({ ...c, side: 'theirs' })),
  ];

  allChanges.sort((a, b) => {
    if (a.baseStart !== b.baseStart) {
      return a.baseStart - b.baseStart;
    }
    return a.side === 'mine' ? -1 : 1;
  });

  const regions = [];

  let i = 0;
  while (i < allChanges.length) {
    const region = {
      baseStart: allChanges[i].baseStart,
      baseEnd: allChanges[i].baseEnd,
      changes: [allChanges[i]],
    };

    // Absorb overlapping changes
    let j = i + 1;
    while (j < allChanges.length && allChanges[j].baseStart <= region.baseEnd) {
      region.changes.push(allChanges[j]);
      region.baseEnd = Math.max(region.baseEnd, allChanges[j].baseEnd);
      j++;
    }

    regions.push(region);
    i = j;
  }

  return regions;
}

// Resolve a region
function resolveRegion(region, mine, base, theirs) {
  const mineChanges = region.changes.filter((c) => c.side === 'mine');
  const theirsChanges = region.changes.filter((c) => c.side === 'theirs');

  const regionStart = region.baseStart;
  const regionEnd = region.baseEnd;
  const baseRegion = base.slice(regionStart, regionEnd);

  if (mineChanges.length === 0) {
    // Only theirs changed
    const sideStart = theirsChanges[0].sideStart;
    const sideEnd = theirsChanges[theirsChanges.length - 1].sideEnd;
    return {
      type: 'theirs',
      lines: theirs.slice(sideStart, sideEnd),
    };
  } else if (theirsChanges.length === 0) {
    // Only mine changed
    const sideStart = mineChanges[0].sideStart;
    const sideEnd = mineChanges[mineChanges.length - 1].sideEnd;
    return {
      type: 'mine',
      lines: mine.slice(sideStart, sideEnd),
    };
  } else {
    // Both sides changed
    const mineStart = Math.min(...mineChanges.map((c) => c.sideStart));
    const mineEnd = Math.max(...mineChanges.map((c) => c.sideEnd));
    const theirsStart = Math.min(...theirsChanges.map((c) => c.sideStart));
    const theirsEnd = Math.max(...theirsChanges.map((c) => c.sideEnd));

    // Move back/forward by how far region extends before/after changes
    const minBaseStart = Math.min(...mineChanges.map((c) => c.baseStart), ...theirsChanges.map((c) => c.baseStart));
    const maxBaseEnd = Math.max(...mineChanges.map((c) => c.baseEnd), ...theirsChanges.map((c) => c.baseEnd));

    const moveBack = minBaseStart - regionStart;
    const moveForward = regionEnd - maxBaseEnd;

    const mineLines = mine.slice(mineStart - moveBack, mineEnd + moveForward);
    const theirsLines = theirs.slice(theirsStart - moveBack, theirsEnd + moveForward);

    if (JSON.stringify(mineLines) === JSON.stringify(theirsLines)) {
      return {
        type: 'both',
        lines: mineLines,
        mineLineCount: mineLines.length,
        baseLineCount: baseRegion.length,
        theirsLineCount: theirsLines.length,
      };
    } else if (JSON.stringify(mineLines) === JSON.stringify(baseRegion)) {
      return {
        type: 'theirs',
        lines: theirsLines,
      };
    } else if (JSON.stringify(theirsLines) === JSON.stringify(baseRegion)) {
      return {
        type: 'mine',
        lines: mineLines,
      };
    } else {
      return {
        type: 'conflict',
        mineLines,
        baseLines: baseRegion,
        theirsLines,
      };
    }
  }
}

// Main function
async function main() {
  const [mine, base, theirs] = await readInput();

  const mineChanges = getChanges(mine, base);
  const theirsChanges = getChanges(theirs, base);

  const regions = getRegions(mineChanges, theirsChanges, base);

  // Generate output
  let hasConflict = false;
  const output = [];
  let currentBaseIdx = 0;

  // Add initial stable region if needed
  if (regions.length === 0 || regions[0].baseStart > 0) {
    const stableEnd = regions.length > 0 ? regions[0].baseStart : base.length;
    output.push(...base.slice(0, stableEnd));
    currentBaseIdx = stableEnd;
  }

  // Process regions
  for (let i = 0; i < regions.length; i++) {
    const region = regions[i];
    const resolution = resolveRegion(region, mine, base, theirs);

    if (mode === 'merge' || mode === 'merge2') {
      if (resolution.type === 'conflict') {
        hasConflict = true;
        output.push('<<<<<<< mine');
        output.push(...resolution.mineLines);
        if (mode === 'merge') {
          output.push('||||||| base');
          output.push(...resolution.baseLines);
        }
        output.push('=======');
        output.push(...resolution.theirsLines);
        output.push('>>>>>>> theirs');
      } else {
        output.push(...resolution.lines);
      }
    } else if (mode === 'regions') {
      if (resolution.type === 'conflict') {
        hasConflict = true;
        output.push(`conflict mine=${resolution.mineLines.length} base=${resolution.baseLines.length} theirs=${resolution.theirsLines.length}`);
      } else if (resolution.type === 'both') {
        output.push(`both ${resolution.lines.length}`);
      } else if (resolution.type === 'mine') {
        output.push(`mine ${resolution.lines.length}`);
      } else if (resolution.type === 'theirs') {
        output.push(`theirs ${resolution.lines.length}`);
      }
    }

    currentBaseIdx = region.baseEnd;

    // Add stable region after this region if there's another region
    if (i + 1 < regions.length) {
      const nextRegion = regions[i + 1];
      if (currentBaseIdx < nextRegion.baseStart) {
        if (mode === 'merge' || mode === 'merge2') {
          output.push(...base.slice(currentBaseIdx, nextRegion.baseStart));
        } else {
          output.push(`stable ${nextRegion.baseStart - currentBaseIdx}`);
        }
        currentBaseIdx = nextRegion.baseStart;
      }
    }
  }

  // Add final stable region
  if (currentBaseIdx < base.length) {
    if (mode === 'merge' || mode === 'merge2') {
      output.push(...base.slice(currentBaseIdx));
    } else {
      output.push(`stable ${base.length - currentBaseIdx}`);
    }
  }

  // Output
  if (output.length > 0) {
    console.log(output.join('\n'));
  }

  process.exit(hasConflict ? 1 : 0);
}

main().catch((err) => {
  process.stderr.write(`error: ${err.message}\n`);
  process.exit(2);
});

